using Marketplace.Domain.Common; namespace Marketplace.Domain.Finance; public sealed class Commission:AggregateRoot<long>{private Commission(){}public long OrderId{get;private set;}public long StoreId{get;private set;}public long SellerId{get;private set;}public long OrderAmountIRR{get;private set;}public decimal CommissionRate{get;private set;}public long MinimumCommissionIRR{get;private set;}public long CalculatedCommissionIRR{get;private set;}public long CommissionAmountIRR{get;private set;}public long SellerAmountIRR{get;private set;}public DateTime CreatedAtUtc{get;private set;}public static Commission Create(long id,long orderId,long storeId,long sellerId,long amount,decimal rate,long minimum){if(amount<0||rate<0||rate>100||minimum<0)throw new DomainException("Invalid commission.");var calc=(long)Math.Floor(amount*rate/100m);var final=Math.Min(amount,Math.Max(calc,minimum));return new(){Id=id,OrderId=orderId,StoreId=storeId,SellerId=sellerId,OrderAmountIRR=amount,CommissionRate=rate,MinimumCommissionIRR=minimum,CalculatedCommissionIRR=calc,CommissionAmountIRR=final,SellerAmountIRR=amount-final,CreatedAtUtc=DateTime.UtcNow};}}
